const payload = $input.first().json;
const alert = {
  service: 'lendloop-n8n',
  severity: 'error',
  workflowName: payload.workflow?.name ?? 'unknown',
  workflowId: payload.workflow?.id ?? null,
  executionId: payload.execution?.id ?? null,
  executionUrl: payload.execution?.url ?? null,
  failedNode: payload.execution?.lastNodeExecuted ?? 'unknown',
  errorMessage: payload.execution?.error?.message ?? 'Unknown workflow error',
  timestamp: new Date().toISOString(),
};

console.error('[LendLoop n8n ERROR]', JSON.stringify(alert));

// In production, connect a Slack / PagerDuty / Email node after this node
// using n8n Credentials so on-call engineers are alerted immediately.
return [{ json: alert }];
